export const ABI_PRODUCTS: AbiProduct[] = ROWS.trim()
  .split('\n')
  .map((row) => {
    const [c, name, slug, group, finish, hex, w, d, h, price, mount, image, description] = row.split('|');
    return {
      cls: ABI_CLASSES[Number(c)],
      name,
      slug,
      group,
      finish,
      hex: hex ? `#${hex}` : undefined,
      width: Number(w),
      depth: Number(d),
      height: Number(h),
      price,
      mount,
      image: image ? `https://www.abiinteriors.com.au/wp-content/uploads/${image}` : undefined,
      description: description ?? '',
    };
  });
